 **/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {LibUniswapOracle} from "./LibUniswapOracle.sol";
import {LibChainlinkOracle} from "./LibChainlinkOracle.sol";
import {IUniswapV3PoolImmutables} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";
import {Implementation} from "contracts/beanstalk/storage/System.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IERC20Decimals {
    function decimals() external view returns (uint8);
}

/**
 * @title Usd Oracle Library
 * @notice Contains functionalty to fetch the manipulation resistant USD price of different tokens.
 * @dev currently supports:
 **/
library LibUsdOracle {
    using LibRedundantMath256 for uint256;

    uint256 constant UNISWAP_DENOMINATOR = 1e6;

    function getUsdPrice(address token) internal view returns (uint256) {
        return getUsdPrice(token, 0);
    }

    /**
     * @dev Returns the price of 1 USD in terms of `token` with the option of using a lookback. (Usd:token Price)
     * `lookback` should be 0 if the instantaneous price is desired. Otherwise, it should be the
     * TWAP lookback in seconds.
     * If using a non-zero lookback, it is recommended to use a substantially large `lookback`
     * (> 900 seconds) to protect against manipulation.
     */
    function getUsdPrice(address token, uint256 lookback) internal view returns (uint256) {
        // call external implementation for token
        // note passing decimals controls pricing order (token:usd vs usd:token)
        return getTokenPriceFromExternal(token, IERC20Decimals(token).decimals(), lookback);
    }

    function getTokenPrice(address token) internal view returns (uint256) {
        return getTokenPrice(token, 0);
    }

    /**
     * @notice returns the price of a given token in USD (token:Usd Price)
     * @dev if ETH returns 1000 USD, this function returns 1000
     * (ignoring decimal precision)
     */
    function getTokenPrice(address token, uint256 lookback) internal view returns (uint256) {
        // call external implementation for token
        return getTokenPriceFromExternal(token, 0, lookback);
    }

    /**
     * @notice gets the token price from an external oracle.
     * @dev if address is 0, use the current contract.
     * If encodeType is 0x01, use the default chainlink implementation.
     * Returns 0 rather than reverting if the call fails.
     * Note: token here refers to the non bean token when quoting for a well price.
     */
    function getTokenPriceFromExternal(
        address token,
        uint256 tokenDecimals,
        uint256 lookback
    ) internal view returns (uint256 tokenPrice) {
        return getTokenPriceFromExternal(token, tokenDecimals, lookback, false);
    }

    /**
     * @notice returns the price of 1 Million USD in terms of `token` with the option of using a lookback.
     * @dev `LibWell.getRatiosAndBeanIndex` attempts to calculate the target ratios by fetching the usdPrice of each token.
     * For tokens with low decimal precision and high prices (ex. WBTC), using the usd:token price would result in a
     * large amount of precision loss. For this reason, tokens with less than 8 decimals use the 1 Million USD price instead..
     */
    function getMillionUsdPrice(address token, uint256 lookback) internal view returns (uint256) {
        return getTokenPriceFromExternal(token, IERC20Decimals(token).decimals(), lookback, true);
    }

    /**
     * @notice internal helper function for `getTokenPriceFromExternal`.
     * @dev the `isMillion` flag is used in `LibChainlinkOracle.getTokenPrice` to
     * return the MILLION_TOKEN2/TOKEN1 price, in cases where the price of TOKEN1 is extremely high (relative to token 2),
     * and when the decimals is very low.
     */
    function getTokenPriceFromExternal(
        address token,
        uint256 tokenDecimals,
        uint256 lookback,
        bool isMillion
    ) private view returns (uint256 tokenPrice) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        Implementation memory oracleImpl = s.sys.oracleImplementation[token];

        // If the encode type is type 1, use the default chainlink implementation instead.
        // `target` refers to the address of the price aggergator implmentation
        if (oracleImpl.encodeType == bytes1(0x01)) {
            return
                LibChainlinkOracle.getTokenPrice(
                    oracleImpl.target, // chainlink Aggergator Address
                    abi.decode(oracleImpl.data, (uint256)), // timeout
                    tokenDecimals, // token decimals
                    lookback,
                    isMillion
                );
        } else if (oracleImpl.encodeType == bytes1(0x02)) {
            // if the encodeType is type 2, use a uniswap oracle implementation.

            // the uniswap oracle implementation combines the use of the chainlink and uniswap oracles.
            // the chainlink oracle is used to get the price of the non-oracle token (for example USDC) in order to
            // use that as a dollar representation
            address chainlinkToken = IUniswapV3PoolImmutables(oracleImpl.target).token0();

            if (chainlinkToken == token) {
                chainlinkToken = IUniswapV3PoolImmutables(oracleImpl.target).token1();
            }

            // get twap from the `chainlinkToken` to `token`
            // exchange 1 `token` for `chainlinkToken`.
            tokenPrice = LibUniswapOracle.getTwap(
                lookback == 0 ? LibUniswapOracle.FIFTEEN_MINUTES : uint32(lookback),
                oracleImpl.target,
                token,
                chainlinkToken,
                tokenDecimals == 0
                    ? uint128(10 ** IERC20Decimals(token).decimals())
                    : uint128(10 ** tokenDecimals)
            );

            // call chainlink oracle from the OracleImplmentation contract
            Implementation memory chainlinkOracle = s.sys.oracleImplementation[chainlinkToken];

            // return the CL_TOKEN/USD or USD/CL_TOKEN, depending on `tokenDecimals`.
            uint256 chainlinkTokenDecimals = IERC20Decimals(chainlinkToken).decimals();
            uint256 chainlinkTokenPrice = LibChainlinkOracle.getTokenPrice(
                chainlinkOracle.target,
                abi.decode(chainlinkOracle.data, (uint256)), // timeout
                tokenDecimals == 0 ? tokenDecimals : chainlinkTokenDecimals,
                lookback,
                false
            );

            // if token decimals != 0, Beanstalk is attempting to query the USD/TOKEN price, and
            // thus the price needs to be inverted.
            if (tokenDecimals != 0) {
                // invert tokenPrice (to get CL_TOKEN/TOKEN).
                // `tokenPrice` has 6 decimal precision (see {LibUniswapOracle.getTwap}).
                // `tokenPrice` is scaled up to 1 million units, if the `isMillion` flag is enabled.
                if (isMillion) {
                    tokenPrice = (1e12 * (10 ** tokenDecimals)) / tokenPrice;
                } else {
                    tokenPrice = (1e6 * (10 ** tokenDecimals)) / tokenPrice;
                }
                // return the USD/TOKEN price.
                // 1e6 * 1e`n` / 1e`n` = 1e6
                return (tokenPrice * chainlinkTokenPrice) / (10 ** chainlinkTokenDecimals);
            }

            return (tokenPrice * chainlinkTokenPrice) / UNISWAP_DENOMINATOR;
        }

        // Non-zero addresses are enforced in verifyOracleImplementation, this is just an extra check.
        if (oracleImpl.target == address(0)) return 0;

        // if `isMillion` is enabled, append the boolean into the oracleImpl,
        // such that the oracle implementation can use the data.
        bytes memory oracleImplData = oracleImpl.data;
        if (isMillion) {
            oracleImplData = abi.encodePacked(oracleImpl.data, isMillion);
        }

        (bool success, bytes memory data) = oracleImpl.target.staticcall(
            abi.encodeWithSelector(oracleImpl.selector, tokenDecimals, lookback, oracleImplData)
        );

        if (!success) return 0;
        assembly {
            tokenPrice := mload(add(data, add(0x20, 0)))
        }
    }
}

contracts/libraries/Silo/LibFlood.sol.content:
/*
 SPDX-License-Identifier: MIT
*/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {IWell} from "contracts/interfaces/basin/IWell.sol";
import {LibWell} from "contracts/libraries/Well/LibWell.sol";
import {Account} from "contracts/beanstalk/storage/Account.sol";
import {LibDeltaB} from "contracts/libraries/Oracle/LibDeltaB.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {BeanstalkERC20} from "contracts/tokens/ERC20/BeanstalkERC20.sol";

/**
 * @author Brean
 * @title LibFlood handles logic relating to flooding.
 **/

library LibFlood {
    using LibRedundantMath256 for uint256;
    // @notice This controls the percentage of Bean supply that is flooded to the field.
    // 1000 represents 1/1000, or 0.1% of total Bean supply.
    uint256 internal constant FLOOD_PODLINE_PERCENT_DENOMINATOR = 1000;

    /**
     * @notice Emitted when Beans are minted to a Well during the Season of Plenty.
     * @param season The Season in which Beans were minted for distribution.
     * @param well The Well that the SOP occurred in.
     * @param token The token that was swapped for Beans.
     * @param amount The amount of tokens which was received for swapping Beans.
     */
    event SeasonOfPlentyWell(uint256 indexed season, address well, address token, uint256 amount);

    /**
     * @notice Emitted when Beans are minted to the Field during the Season of Plenty.
     * @param toField The amount of Beans which were distributed to remaining Pods in the Field.
     */
    event SeasonOfPlentyField(uint256 toField);

    // @dev In-memory struct used to store current deltaB, and then reduction amount per-well.
    struct WellDeltaB {
        address well;
        int256 deltaB;
    }

    /**
     * @dev Oversaturated was previously referred to as Raining and thus code
     * references mentioning Rain really refer to Oversaturation. If P > 1 and the
     * Pod Rate is less than 5%, the Farm is Oversaturated. If it is Oversaturated
     * for a Season, each Season in which it continues to be Oversaturated, it Floods.
     */
    function handleRain(uint256 caseId) external {
        AppStorage storage s = LibAppStorage.diamondStorage();
        // cases % 36  3-8 represent the case where the pod rate is less than 5% and P > 1.
        if (caseId.mod(36) < 3 || caseId.mod(36) > 8) {
            if (s.sys.season.raining) {
                s.sys.season.raining = false;
            }
            return;
        } else if (!s.sys.season.raining) {
            initRainVariables();
            startRain();
        } else {
            // flood podline first, because it checks current Bean supply
            floodPodline();

            if (s.sys.rain.roots > 0) {
                (
                    WellDeltaB[] memory wellDeltaBs,
                    uint256 totalPositiveDeltaB,
                    uint256 totalNegativeDeltaB,
                    uint256 positiveDeltaBCount
                ) = getWellsByDeltaB();
                wellDeltaBs = calculateSopPerWell(
                    wellDeltaBs,
                    totalPositiveDeltaB,
                    totalNegativeDeltaB,
                    positiveDeltaBCount
                );

                for (uint i; i < wellDeltaBs.length; i++) {
                    sopWell(wellDeltaBs[i]);
                }

                s.sys.season.lastSop = s.sys.season.rainStart;
                s.sys.season.lastSopSeason = s.sys.season.current;
            }
        }
    }

    /**
     * @notice Snapshot variables required to start raining.
     */
    function initRainVariables() internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        s.sys.season.raining = true;
        address[] memory wells = LibWhitelistedTokens.getCurrentlySoppableWellLpTokens();
        // Set the plenty per root equal to previous rain start.
        uint32 season = s.sys.season.current;
        uint32 rainstartSeason = s.sys.season.rainStart;
        for (uint i; i < wells.length; i++) {
            s.sys.sop.sops[season][wells[i]] = s.sys.sop.sops[rainstartSeason][wells[i]];
        }
        s.sys.season.rainStart = s.sys.season.current;
        s.sys.rain.pods = s.sys.fields[s.sys.activeField].pods;
        s.sys.rain.roots = s.sys.silo.roots;
    }

    /**
     * @notice Handles any system-level logic that occurs when it starts raining.
     */
    function startRain() internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // upon rain, set beanToMaxLpGpPerBdvRatio to zero, to encourage converts down before starting to flood
        s.sys.seedGauge.beanToMaxLpGpPerBdvRatio = 0;
    }

    /**
     * @dev internal account-level logic to handle when beanstalk is raining. Called from mow.
     */
    function handleRainAndSops(
        address account,
        uint32 lastUpdate,
        uint256 firstGerminatingRoots
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // If a Sop has occured since last update, calculate rewards and set last Sop.
        if (s.sys.season.lastSopSeason > lastUpdate) {
            address[] memory tokens = LibWhitelistedTokens.getSoppableWellLpTokens(); // includes de-whitelisted tokens
            for (uint i; i < tokens.length; i++) {
                s.accts[account].sop.perWellPlenty[tokens[i]].plenty = balanceOfPlenty(
                    account,
                    tokens[i]
                );
            }
            s.accts[account].lastSop = s.sys.season.lastSop;
        }
        // If no roots, reset Sop counters variables
        if (s.accts[account].roots == 0) {
            s.accts[account].lastSop = s.sys.season.rainStart;
            s.accts[account].lastRain = 0;
            return;
        }

        if (s.sys.season.raining) {
            // If rain started after update, set account variables to track rain.
            if (s.sys.season.rainStart > lastUpdate) {
                s.accts[account].lastRain = s.sys.season.rainStart;
                s.accts[account].sop.rainRoots = s.accts[account].roots;
                if (s.sys.season.rainStart - 1 == lastUpdate) {
                    if (firstGerminatingRoots > 0) {
                        // if the account had just finished germinating roots this season (i.e,
                        // deposited in the previous season before raining, and mowed during a sop),
                        // Beanstalk will not allocate plenty to this deposit, and thus the roots
                        // needs to be deducted from the sop roots.
                        s.accts[account].sop.rainRoots = s.accts[account].sop.rainRoots.sub(
                            firstGerminatingRoots
                        );
                    }
                }

                //  s.accts[account].roots includes newly finished germinating roots from a fresh deposit
                //  @ season before rainStart
            }
            // If there has been a Sop since rain started,
            // save plentyPerRoot in case another SOP happens during rain.
            if (s.sys.season.lastSop == s.sys.season.rainStart) {
                address[] memory tokens = LibWhitelistedTokens.getSoppableWellLpTokens(); // includes de-whitelisted tokens (need to update account-level PPR for all tokens)
                for (uint i; i < tokens.length; i++) {
                    s.accts[account].sop.perWellPlenty[tokens[i]].plentyPerRoot = s.sys.sop.sops[
                        s.sys.season.lastSop
                    ][tokens[i]];
                }
            }
        } else if (s.accts[account].lastRain > 0) {
            // Reset Last Rain if not raining.
            s.accts[account].lastRain = 0;
        }
    }

    /**
     * @dev returns the amount of `plenty` an account has.
     */
    function balanceOfPlenty(address account, address well) internal view returns (uint256 plenty) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        Account storage a = s.accts[account];
        plenty = a.sop.perWellPlenty[well].plenty;
        uint256 previousPPR;

        // If lastRain > 0, then check if SOP occured during the rain period.
        if (s.accts[account].lastRain > 0) {
            // if the last processed SOP = the lastRain processed season,
            // then we use the stored roots to get the delta.
            if (a.lastSop == a.lastRain) {
                previousPPR = a.sop.perWellPlenty[well].plentyPerRoot;
            } else {
                previousPPR = s.sys.sop.sops[a.lastSop][well];
            }
            uint256 lastRainPPR = s.sys.sop.sops[s.accts[account].lastRain][well];

            // If there has been a SOP duing the rain sesssion since last update, process SOP.
            if (lastRainPPR > previousPPR) {
                uint256 plentyPerRoot = lastRainPPR - previousPPR;
                previousPPR = lastRainPPR;
                plenty = plenty.add(
                    plentyPerRoot.mul(s.accts[account].sop.rainRoots).div(C.SOP_PRECISION)
                );
            }
        } else {
            // If it was not raining, just use the PPR at previous SOP.
            previousPPR = s.sys.sop.sops[s.accts[account].lastSop][well];
        }

        // Handle and SOPs that started + ended before after last Silo update.
        if (s.sys.season.lastSop > s.accts[account].lastUpdate) {
            uint256 plentyPerRoot = s.sys.sop.sops[s.sys.season.lastSop][well].sub(previousPPR);
            plenty = plenty.add(plentyPerRoot.mul(s.accts[account].roots).div(C.SOP_PRECISION));
        }
    }

    /**
     * @notice Floods the field, up to 0.1% of the total Bean supply worth of pods.
     */
    function floodPodline() private {
        AppStorage storage s = LibAppStorage.diamondStorage();
        // Make 0.1% of the total bean supply worth of pods harvestable.

        uint256 totalBeanSupply = BeanstalkERC20(s.sys.tokens.bean).totalSupply();
        uint256 sopFieldBeans = totalBeanSupply.div(FLOOD_PODLINE_PERCENT_DENOMINATOR); // 1/1000 = 0.1% of total supply

        // Note there may be cases where zero harvestable pods are available. For clarity, the code will still emit an event
        // but with zero sop field beans.
        uint256 maxHarvestable = s.sys.fields[s.sys.activeField].pods.sub(
            s.sys.fields[s.sys.activeField].harvestable
        );

        sopFieldBeans = sopFieldBeans > maxHarvestable ? maxHarvestable : sopFieldBeans;

        s.sys.fields[s.sys.activeField].harvestable = s
            .sys
            .fields[s.sys.activeField]
            .harvestable
            .add(sopFieldBeans);
        BeanstalkERC20(s.sys.tokens.bean).mint(address(this), sopFieldBeans);

        emit SeasonOfPlentyField(sopFieldBeans);
    }

    function getWellsByDeltaB()
        internal
        view
        returns (
            WellDeltaB[] memory wellDeltaBs,
            uint256 totalPositiveDeltaB,
            uint256 totalNegativeDeltaB,
            uint256 positiveDeltaBCount
        )
    {
        address[] memory wells = LibWhitelistedTokens.getCurrentlySoppableWellLpTokens();
        wellDeltaBs = new WellDeltaB[](wells.length);

        for (uint i = 0; i < wells.length; i++) {
            wellDeltaBs[i] = WellDeltaB(wells[i], LibDeltaB.currentDeltaB(wells[i]));
            if (wellDeltaBs[i].deltaB > 0) {
                totalPositiveDeltaB += uint256(wellDeltaBs[i].deltaB);
                positiveDeltaBCount++;
            } else {
                totalNegativeDeltaB += uint256(-wellDeltaBs[i].deltaB);
            }
        }

        // Sort the wellDeltaBs array
        quickSort(wellDeltaBs, 0, int(wellDeltaBs.length - 1));
    }

    function quickSort(
        WellDeltaB[] memory arr,
        int left,
        int right
    ) internal pure returns (WellDeltaB[] memory) {
        if (left >= right) return arr;

        // Choose the median of left, right, and middle as pivot (improves performance on random data)
        uint mid = uint(left) + (uint(right) - uint(left)) / 2;
        WellDeltaB memory pivot;

        if (arr[uint(left)].deltaB > arr[uint(mid)].deltaB) {
            if (arr[uint(left)].deltaB < arr[uint(right)].deltaB) {
                pivot = arr[uint(left)];
            } else {
                if (arr[uint(right)].deltaB > arr[uint(mid)].deltaB) {
                    pivot = arr[uint(right)];
                } else {
                    pivot = arr[uint(mid)];
                }
            }
        } else {
            if (arr[uint(mid)].deltaB < arr[uint(right)].deltaB) {
                pivot = arr[uint(mid)];
            } else {
                if (arr[uint(right)].deltaB > arr[uint(left)].deltaB) {
                    pivot = arr[uint(right)];
                } else {
                    pivot = arr[uint(left)];
                }
            }
        }

        int i = left;
        int j = right;
        while (i <= j) {
            while (arr[uint(i)].deltaB > pivot.deltaB) i++;
            while (pivot.deltaB > arr[uint(j)].deltaB) j--;
            if (i <= j) {
                (arr[uint(i)], arr[uint(j)]) = (arr[uint(j)], arr[uint(i)]);
                i++;
                j--;
            }
        }

        if (left < j) {
            arr = quickSort(arr, left, j);
        }
        if (i < right) {
            return quickSort(arr, i, right);
        }
        return arr;
    }

    /**
     * @dev Flood was previously called a "Season of Plenty" (SOP for short).
     * When Beanstalk has been Oversaturated for a Season, Beanstalk returns the
     * Bean price to its peg by minting additional Beans and selling them directly
     * on the sop well. Proceeds from the sale in the form of WETH are distributed to
     * Stalkholders at the beginning of a Season in proportion to their Stalk
     * ownership when the Farm became Oversaturated. Also, at the beginning of the
     * Flood, all Pods that were minted before the Farm became Oversaturated Ripen
     * and become Harvestable.
     * For more information On Oversaturation see {handleRain}.
     */
    function sopWell(WellDeltaB memory wellDeltaB) private {
        AppStorage storage s = LibAppStorage.diamondStorage();
        if (wellDeltaB.deltaB > 0) {
            IERC20 sopToken = LibWell.getNonBeanTokenFromWell(wellDeltaB.well);

            uint256 sopBeans = uint256(wellDeltaB.deltaB);
            BeanstalkERC20(s.sys.tokens.bean).mint(address(this), sopBeans);

            // Approve and Swap Beans for the non-bean token of the SOP well.
            BeanstalkERC20(s.sys.tokens.bean).approve(wellDeltaB.well, sopBeans);
            uint256 amountOut = IWell(wellDeltaB.well).swapFrom(
                BeanstalkERC20(s.sys.tokens.bean),
                sopToken,
                sopBeans,
                0,
                address(this),
                type(uint256).max
            );
            rewardSop(wellDeltaB.well, amountOut, address(sopToken));
            emit SeasonOfPlentyWell(
                s.sys.season.current,
                wellDeltaB.well,
                address(sopToken),
                amountOut
            );
        }
    }

    /**
     * @dev Allocate `sop token` during a Season of Plenty.
     */
    function rewardSop(address well, uint256 amount, address sopToken) private {
        AppStorage storage s = LibAppStorage.diamondStorage();
        s.sys.sop.sops[s.sys.season.rainStart][well] = s
        .sys
        .sop
        .sops[s.sys.season.lastSop][well].add(amount.mul(C.SOP_PRECISION).div(s.sys.rain.roots));

        // update Beanstalk's stored overall plenty for this well
        s.sys.sop.plentyPerSopToken[sopToken] += amount;
    }

    /*
     * @notice Calculates the amount of beans per well that should be minted in a sop.
     * @param wellDeltaBs The deltaBs of all whitelisted wells in which to flood. Must be sorted in descending order.
     */
    function calculateSopPerWell(
        WellDeltaB[] memory wellDeltaBs,
        uint256 totalPositiveDeltaB,
        uint256 totalNegativeDeltaB,
        uint256 positiveDeltaBCount
    ) internal pure returns (WellDeltaB[] memory) {
        // most likely case is that all deltaBs are positive
        if (positiveDeltaBCount == wellDeltaBs.length) {
            // if all deltaBs are positive, need to sop all to zero, so return existing deltaBs
            return wellDeltaBs;
        }

        if (totalPositiveDeltaB < totalNegativeDeltaB || positiveDeltaBCount == 0) {
            // The less than conditional can occur if the twaDeltaB is positive, but the instanteous deltaB is negative or 0
            // In that case, no reductions are needed.
            // If there are no positive values, no well flooding is needed, return zeros
            for (uint256 i = 0; i < positiveDeltaBCount; i++) {
                wellDeltaBs[i].deltaB = 0;
            }
            return wellDeltaBs;
        }

        if (totalPositiveDeltaB < totalNegativeDeltaB) {
            for (uint256 i = 0; i < positiveDeltaBCount; i++) {
                wellDeltaBs[i].deltaB = 0;
            }
            return wellDeltaBs;
        }

        uint256 shaveToLevel = totalNegativeDeltaB / positiveDeltaBCount;

        // Loop through positive deltaB wells starting at the highest, re-use the deltaB value slot
        // as reduction amount (amount of beans to flood per well).
        for (uint256 i = positiveDeltaBCount; i > 0; i--) {
            if (shaveToLevel > uint256(wellDeltaBs[i - 1].deltaB)) {
                shaveToLevel += (shaveToLevel - uint256(wellDeltaBs[i - 1].deltaB)) / (i - 1);
                // amount to sop for this well must be zero
                wellDeltaBs[i - 1].deltaB = 0;
            } else {
                wellDeltaBs[i - 1].deltaB = wellDeltaBs[i - 1].deltaB - int256(shaveToLevel);
            }
        }
        return wellDeltaBs;
    }
}

contracts/libraries/Silo/LibGerminate.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {LibAppStorage} from "../LibAppStorage.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {Deposited, GerminatingSilo, GerminationSide} from "contracts/beanstalk/storage/System.sol";
import {LibRedundantMath128} from "../LibRedundantMath128.sol";
import {LibRedundantMath32} from "../LibRedundantMath32.sol";
import {LibRedundantMathSigned96} from "../LibRedundantMathSigned96.sol";
import {LibTokenSilo} from "./LibTokenSilo.sol";
import {LibSilo} from "./LibSilo.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {C} from "../../C.sol";

/**
 * @title LibGerminate
 * @author Brean
 * @notice LibGerminate handles logic associated with germination.
 * @dev "germinating" values are values that are currently inactive.
 * germinating values stay germinating until the 1 + the remainder of the current season as passed,
 * in which case they become active.
 *
 * The following are germinating:
 * - newly issued stalk (from new deposits or mowing)
 * - roots from newly issued stalk
 * - new bdv introduced in the silo.
 */
library LibGerminate {
    using LibRedundantMath256 for uint256;
    using SafeCast for uint256;
    using LibRedundantMath32 for uint32;
    using LibRedundantMath128 for uint128;
    using LibRedundantMathSigned96 for int96;

    //////////////////////// EVENTS ////////////////////////

    /**
     * @notice emitted when the farmers germinating stalk changes.
     */
    event FarmerGerminatingStalkBalanceChanged(
        address indexed account,
        int256 delta,
        GerminationSide germ
    );

    /**
     * @notice emitted when the total germinating amount/bdv changes.
     * @param germinationSeason the season the germination occured.
     * Does not always equal the current season.
     * @param token the token being updated.
     * @param deltaAmount the change in the total germinating amount.
     * @param deltaBdv the change in the total germinating bdv.
     */
    event TotalGerminatingBalanceChanged(
        uint256 germinationSeason,
        address indexed token,
        int256 deltaAmount,
        int256 deltaBdv
    );

    /**
     * @notice emitted when the total germinating stalk changes.
     * @param germinationSeason issuance season of germinating stalk
     * @param deltaGerminatingStalk the change in the total germinating stalk.
     * @dev the issuance season may differ from the season that this event was emitted in..
     */
    event TotalGerminatingStalkChanged(uint256 germinationSeason, int256 deltaGerminatingStalk);

    /**
     * @notice emitted at the sunrise function when the total stalk and roots are incremented.
     * @dev currently, stalk and roots can only increase at the end of `endTotalGermination`,
     * but is casted in the event to allow for future decreases.
     */
    event TotalStalkChangedFromGermination(int256 deltaStalk, int256 deltaRoots);

    struct GermStem {
        int96 germinatingStem;
        int96 stemTip;
    }

    /**
     * @notice Ends the germination process of system-wide values.
     * @dev we calculate the unclaimed germinating roots of 2 seasons ago
     * as the roots of the stalk should be calculated based on the total stalk
     * when germination finishes, rather than when germination starts.
     */
    function endTotalGermination(uint32 season, address[] memory tokens) external {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // germination can only occur after season 3.
        if (season < 2) return;
        uint32 germinationSeason = season.sub(2);

        // base roots are used if there are no roots in the silo.
        // root calculation is skipped if no deposits have been made
        // in the season.
        uint256 finishedGerminatingStalk = s.sys.silo.unclaimedGerminating[germinationSeason].stalk;
        uint256 rootsFromGerminatingStalk;
        if (s.sys.silo.roots == 0) {
            rootsFromGerminatingStalk = finishedGerminatingStalk.mul(C.getRootsBase());
        } else if (s.sys.silo.unclaimedGerminating[germinationSeason].stalk > 0) {
            rootsFromGerminatingStalk = s.sys.silo.roots.mul(finishedGerminatingStalk).div(
                s.sys.silo.stalk
            );
        }
        s.sys.silo.unclaimedGerminating[germinationSeason].roots = rootsFromGerminatingStalk;
        // increment total stalk and roots based on unclaimed values.
        s.sys.silo.stalk = s.sys.silo.stalk.add(finishedGerminatingStalk);
        s.sys.silo.roots = s.sys.silo.roots.add(rootsFromGerminatingStalk);

        // increment total deposited and amounts for each token.
        GerminationSide side = getSeasonGerminationSide();
        for (uint i; i < tokens.length; ++i) {
            // if the token has no deposits, skip.
            if (s.sys.silo.germinating[side][tokens[i]].amount == 0) {
                continue;
            }

            LibTokenSilo.incrementTotalDeposited(
                tokens[i],
                s.sys.silo.germinating[side][tokens[i]].amount,
                s.sys.silo.germinating[side][tokens[i]].bdv
            );

            // emit events.
            emit TotalGerminatingBalanceChanged(
                germinationSeason,
                tokens[i],
                -int256(uint256(s.sys.silo.germinating[side][tokens[i]].amount)),
                -int256(uint256(s.sys.silo.germinating[side][tokens[i]].bdv))
            );
            // clear deposited values.
            delete s.sys.silo.germinating[side][tokens[i]];
        }

        // emit change in total germinating stalk.
        emit TotalGerminatingStalkChanged(
            germinationSeason,
            -int256(uint256(finishedGerminatingStalk))
        );
        emit TotalStalkChangedFromGermination(
            int256(uint256(finishedGerminatingStalk)),
            int256(uint256(rootsFromGerminatingStalk))
        );
    }

    /**
     * @notice contains logic for ending germination for stalk and roots.
     * @param account address of the account to end germination for.
     * @param lastMowedSeason the last season the account mowed.
     *
     * @dev `first` refers to the set of germinating stalk
     * and roots created in the season closest to the current season.
     * i.e if a user deposited in season 10 and 11, the `first` stalk
     * would be season 11.
     *
     * the germination process:
     * - increments the assoicated values (bdv, stalk, roots)
     * - clears the germination struct for the account.
     *
     * @return firstGerminatingRoots the roots from the first germinating stalk.
     * used in {handleRain} to properly set the rain roots of a user,
     * if the user had deposited in the season prior to a rain.
     */
    function endAccountGermination(
        address account,
        uint32 lastMowedSeason,
        uint32 currentSeason
    ) internal returns (uint256 firstGerminatingRoots) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        bool lastUpdateOdd = isSeasonOdd(lastMowedSeason);
        (uint256 firstStalk, uint256 secondStalk) = getGerminatingStalk(account, lastUpdateOdd);
        uint256 totalRootsFromGermination;
        uint256 germinatingStalk;

        // check to end germination for first stalk.
        // if last mowed season is greater or equal than (currentSeason - 1),
        // then the first stalk is still germinating.
        if (firstStalk > 0 && lastMowedSeason < currentSeason.sub(1)) {
            (uint256 roots, GerminationSide germState) = claimGerminatingRoots(
                account,
                lastMowedSeason,
                firstStalk,
                lastUpdateOdd
            );
            germinatingStalk = firstStalk;
            totalRootsFromGermination = roots;
            firstGerminatingRoots = roots;
            emit FarmerGerminatingStalkBalanceChanged(
                account,
                -int256(uint256(germinatingStalk)),
                germState
            );
        }

        // check to end germination for second stalk.
        if (secondStalk > 0) {
            (uint256 roots, GerminationSide germState) = claimGerminatingRoots(
                account,
                lastMowedSeason.sub(1),
                secondStalk,
                !lastUpdateOdd
            );
            germinatingStalk = germinatingStalk.add(secondStalk);
            totalRootsFromGermination = totalRootsFromGermination.add(roots);
            emit FarmerGerminatingStalkBalanceChanged(
                account,
                -int256(uint256(secondStalk)),
                germState
            );
        }

        // increment users stalk and roots.
        if (germinatingStalk > 0) {
            s.accts[account].stalk = s.accts[account].stalk.add(germinatingStalk);
            s.accts[account].roots = s.accts[account].roots.add(totalRootsFromGermination);

            // emit event. Active stalk is incremented, germinating stalk is decremented.
            emit LibSilo.StalkBalanceChanged(
                account,
                int256(uint256(germinatingStalk)),
                int256(uint256(totalRootsFromGermination))
            );
        }
    }

    /**
     * @notice Claims the germinating roots of an account,
     * as well as clears the germinating stalk and roots.
     *
     * @param account address of the account to end germination for.
     * @param season the season to calculate the germinating roots for.
     * @param stalk the stalk to calculate the germinating roots for.
     * @param clearOdd whether to clear the odd or even germinating stalk.
     */
    function claimGerminatingRoots(
        address account,
        uint32 season,
        uint256 stalk,
        bool clearOdd
    ) private returns (uint256 roots, GerminationSide germState) {
        AppStorage storage s = LibAppStorage.diamondStorage();

        roots = calculateGerminatingRoots(season, stalk);

        if (clearOdd) {
            delete s.accts[account].germinatingStalk[GerminationSide.ODD];
            germState = GerminationSide.ODD;
        } else {
            delete s.accts[account].germinatingStalk[GerminationSide.EVEN];
            germState = GerminationSide.EVEN;
        }

        // deduct from unclaimed values.
        s.sys.silo.unclaimedGerminating[season].stalk = s
            .sys
            .silo
            .unclaimedGerminating[season]
            .stalk
            .sub(stalk);
        s.sys.silo.unclaimedGerminating[season].roots = s
            .sys
            .silo
            .unclaimedGerminating[season]
            .roots
            .sub(roots);
    }

    /**
     * @notice calculates the germinating roots for a given stalk and season.
     * @param season the season to use when calculating the germinating roots.
     * @param stalk the stalk to calculate the germinating roots for.
     */
    function calculateGerminatingRoots(
        uint32 season,
        uint256 stalk
    ) private view returns (uint256 roots) {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // if the stalk is equal to the remaining unclaimed germinating stalk,
        // then return the remaining unclaimed germinating roots.
        if (stalk == s.sys.silo.unclaimedGerminating[season].stalk) {
            roots = s.sys.silo.unclaimedGerminating[season].roots;
        } else {
            // calculate the roots:
            roots = uint256(stalk).mul(s.sys.silo.unclaimedGerminating[season].roots).div(
                s.sys.silo.unclaimedGerminating[season].stalk
            );
        }
    }

    /**
     * @notice returns the germinatingStalk of the account,
     * ordered based on the parity of lastUpdate.
     * @dev if lastUpdate is odd, then `firstStalk` is the odd stalk.
     */
    function getGerminatingStalk(
        address account,
        bool lastUpdateOdd
    ) internal view returns (uint128 firstStalk, uint128 secondStalk) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        if (lastUpdateOdd) {
            firstStalk = s.accts[account].germinatingStalk[GerminationSide.ODD];
            secondStalk = s.accts[account].germinatingStalk[GerminationSide.EVEN];
        } else {
            firstStalk = s.accts[account].germinatingStalk[GerminationSide.EVEN];
            secondStalk = s.accts[account].germinatingStalk[GerminationSide.ODD];
        }
    }

    /**
     * @notice returns the germinating stalk and roots that will finish germinating
     * upon an interaction with the silo.
     */
    function getFinishedGerminatingStalkAndRoots(
        address account,
        uint32 lastMowedSeason,
        uint32 currentSeason
    ) internal view returns (uint256 germinatingStalk, uint256 germinatingRoots) {
        // if user has mowed already,
        // then there are no germinating stalk and roots to finish.
        if (lastMowedSeason == currentSeason) {
            return (0, 0);
        }

        (uint128 firstStalk, uint128 secondStalk) = getGerminatingStalk(
            account,
            isSeasonOdd(lastMowedSeason)
        );

        // check to end germination for first stalk.
        // if last mowed season is the greater or equal than (currentSeason - 1),
        // then the first stalk is still germinating.
        if (firstStalk > 0 && lastMowedSeason < currentSeason.sub(1)) {
            germinatingStalk = firstStalk;
            germinatingRoots = calculateGerminatingRoots(lastMowedSeason, firstStalk);
        }

        // check to end germination for second stalk.
        if (secondStalk > 0) {
            germinatingStalk = germinatingStalk.add(secondStalk);
            germinatingRoots = germinatingRoots.add(
                calculateGerminatingRoots(lastMowedSeason.sub(1), secondStalk)
            );
        }
    }

    /**
     * @notice returns the stalk currently germinating for an account.
     * Does not include germinating stalk that will finish germinating
     * upon an interaction with the silo.
     */
    function getCurrentGerminatingStalk(
        address account,
        uint32 lastMowedSeason
    ) internal view returns (uint256 germinatingStalk) {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // if the last mowed season is less than the current season - 1,
        // then there are no germinating stalk and roots (as all germinating assets have finished).
        if (lastMowedSeason < s.sys.season.current.sub(1)) {
            return 0;
        } else {
            (uint128 firstStalk, uint128 secondStalk) = getGerminatingStalk(
                account,
                isSeasonOdd(lastMowedSeason)
            );
            germinatingStalk = firstStalk.add(secondStalk);
        }
    }

    /**
     * @notice returns the unclaimed germinating stalk and roots.
     */
    function getUnclaimedGerminatingStalkAndRoots(
        uint32 season
    ) internal view returns (GerminatingSilo memory unclaimed) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        unclaimed = s.sys.silo.unclaimedGerminating[season];
    }

    /**
     * @notice returns the total germinating bdv and amount for a token.
     */
    function getTotalGerminatingForToken(
        address token
    ) internal view returns (uint256 bdv, uint256 amount) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return (
            s.sys.silo.germinating[GerminationSide.ODD][token].bdv +
                s.sys.silo.germinating[GerminationSide.EVEN][token].bdv,
            s.sys.silo.germinating[GerminationSide.ODD][token].amount +
                s.sys.silo.germinating[GerminationSide.EVEN][token].amount
        );
    }

    /**
     * @notice determines whether a deposit (token + stem) should be germinating or not.
     * If germinating, determines whether the deposit should be set to even or odd.
     *
     * @dev `getGerminationState` should be used if the stemTip and germinatingStem
     * have not been calculated yet. Otherwise, use `_getGerminationState` for gas effiecnecy.
     */
    function getGerminationState(
        address token,
        int96 stem
    ) internal view returns (GerminationSide, int96) {
        GermStem memory germStem = getGerminatingStem(token);
        return (_getGerminationState(stem, germStem), germStem.stemTip);
    }

    /**
     * @notice returns the `germinating` stem of a token.
     * @dev the 'germinating' stem is the stem where deposits that have a stem
     * equal or higher than this value are germinating.
     */
    function getGerminatingStem(address token) internal view returns (GermStem memory germStem) {
        germStem.stemTip = LibTokenSilo.stemTipForToken(token);
        germStem.germinatingStem = _getGerminatingStem(token, germStem.stemTip);
    }

    /**
     * @notice returns the `germinating` stem of a token.
     * @dev the 'germinating' stem is the stem where deposits that have a stem
     * equal or higher than this value are germinating.
     */
    function _getGerminatingStem(address token, int96 stemTip) internal view returns (int96 stem) {
        return __getGerminatingStem(stemTip, int96(uint96(getPrevStalkEarnedPerSeason(token))));
    }

    /**
     * @notice Gas efficent version of `_getGerminatingStem`.
     *
     * @dev use when the stemTip and germinatingStem have already been calculated.
     * Assumes the same token is used.
     * prevStalkEarnedPerSeason is the stalkEarnedPerSeason of the previous season.
     * since `lastStemTip` + `prevStalkEarnedPerSeason` is the current stemTip,
     * safeMath is not needed.
     */
    function __getGerminatingStem(
        int96 stemTip,
        int96 prevStalkEarnedPerSeason
    ) internal pure returns (int96 stem) {
        return stemTip - prevStalkEarnedPerSeason;
    }

    /**
     * @notice returns the stalkEarnedPerSeason of a token of the previous season.
     * @dev if the milestone season is not the current season, then the stalkEarnedPerSeason
     * hasn't changed from the previous season. Otherwise, we calculate the prevStalkEarnedPerSeason.
     */

    function getPrevStalkEarnedPerSeason(
        address token
    ) private view returns (uint32 prevStalkEarnedPerSeason) {
        AppStorage storage s = LibAppStorage.diamondStorage();

        if (s.sys.silo.assetSettings[token].milestoneSeason < s.sys.season.current) {
            prevStalkEarnedPerSeason = s.sys.silo.assetSettings[token].stalkEarnedPerSeason;
        } else {
            int32 deltaStalkEarnedPerSeason = s
                .sys
                .silo
                .assetSettings[token]
                .deltaStalkEarnedPerSeason;
            if (deltaStalkEarnedPerSeason >= 0) {
                prevStalkEarnedPerSeason =
                    s.sys.silo.assetSettings[token].stalkEarnedPerSeason -
                    uint32(deltaStalkEarnedPerSeason);
            } else {
                prevStalkEarnedPerSeason =
                    s.sys.silo.assetSettings[token].stalkEarnedPerSeason +
                    uint32(-deltaStalkEarnedPerSeason);
            }
        }
    }

    /**
     * @notice internal function for germination stem.
     * @dev a deposit is germinating if the stem is the stemTip or the germinationStem.
     * the 'germinationStem` is the stem of the token of the previous season.
     *
     * The function must check whether the stem is equal to the germinationStem,
     * to determine which germination state it is in.
     */
    function _getGerminationState(
        int96 stem,
        GermStem memory germData
    ) internal view returns (GerminationSide) {
        if (stem < germData.germinatingStem) {
            // if the stem of the deposit is lower than the germination stem,
            // then the deposit is not germinating.
            return GerminationSide.NOT_GERMINATING;
        } else {
            // return the gemination state based on whether the stem
            // is equal to the stemTip.
            // if the stem is equal to the stem tip, it is in the initial stages of germination.
            // if the stem is not equal to the stemTip, its in the germination process.
            if (stem == germData.stemTip) {
                return isCurrentSeasonOdd() ? GerminationSide.ODD : GerminationSide.EVEN;
            } else {
                return isCurrentSeasonOdd() ? GerminationSide.EVEN : GerminationSide.ODD;
            }
        }
    }

    /**
     * @notice returns the germination side for the current season.
     * @dev used in new deposits, as all new deposits are germinating.
     */
    function getSeasonGerminationSide() internal view returns (GerminationSide) {
        return isCurrentSeasonOdd() ? GerminationSide.ODD : GerminationSide.EVEN;
    }

    /**
     * @notice returns the germination state for a given season.
     */
    function getGerminationStateForSeason(uint32 season) internal pure returns (GerminationSide) {
        return isSeasonOdd(season) ? GerminationSide.ODD : GerminationSide.EVEN;
    }

    /**
     * @notice returns whether the current season is odd. Used for Germination.
     * @dev even % 2 = 0 (false), odd % 2 = 1 (true)
     */
    function isCurrentSeasonOdd() internal view returns (bool) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return isSeasonOdd(s.sys.season.current);
    }

    /**
     * @notice returns whether `season` is odd.
     */
    function isSeasonOdd(uint32 season) internal pure returns (bool) {
        return season.mod(2) == 0 ? false : true;
    }
}

